        left[i] = static_cast<float>(i);
        right[i] = static_cast<float>(i) + 0.5f;
    }

    dim3 grid(size, 1, 1);
    dim3 block(block_size, 1, 1);

    add <<<grid, block>>> (left, right, output);

    // Launch the test kernel
    test_grid_dim <<<grid, block>>> ();

    cudaFree(left);
    cudaFree(right);
    cudaFree(output);

    return 0;
}
